import React, {
    useEffect,
    useCallback,
    useRef
} from 'react';

import {
    View,
    FlatList
} from 'react-native';

import { useContexState } from '../../hooks/context';
import { useLoadPage } from '../../hooks/loadPage';

import { ListFooter } from '../../components/ListFooter';
import { ListHeader } from '../../components/ListHeader';
import { ListItem } from '../../components/ListItem';

import { styles } from './styles';

export function RenderList() {
    const { listData } = useContexState();
    const { LoadPage, getList } = useLoadPage();
    const refContainer = useRef<FlatList>(null);

    useEffect(() => {
       if(!listData[0]?.firstCard) LoadPage();
    }, []);

    const renderItem = useCallback(
        ({ item }) =>
            <ListItem data={item} list={getList} />,
        [getList]
    );

    const keyExtractor = useCallback(
        (item) => item.id.toString(), []
    );

    (function () {
        if (listData[0]?.firstCard) {
            refContainer.current?.scrollToIndex({
                index: 0,
                animated: false,
            });
        };
    })();

    return (
        <View style={styles.listContainer}>
            <FlatList
                viewabilityConfig={{
                    viewAreaCoveragePercentThreshold: 10,
                }}
                ref={refContainer}
                initialNumToRender={10}
                key="list"
                data={listData}
                windowSize={80}
                showsVerticalScrollIndicator={false}
                renderItem={renderItem}
                keyExtractor={keyExtractor}
                updateCellsBatchingPeriod={50}
                ListHeaderComponent={ListHeader}
                ListFooterComponent={ListFooter}
            />
        </View>
    );
};
